package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real persistence and fenced access to opaque test bytes, not an actual workbook/store/Worker proof. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetExportPrepareIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",ROUTE="POST /integration/export-prepare-accept";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository exports;static ObjectMapper mapper;static String admin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(4);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);exports=new PostgresAssetExportRepository(pool,platform);admin=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("padmin")).isPresent()).findFirst().orElseThrow().id();}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static AssetExportJobRepository.Access access(){return new AssetExportJobRepository.Access(admin,TENANT,platform.membership(admin,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Job accept(String key){var a=access();return mapper.convertValue(platform.idempotentAuthorized(admin,TENANT,ROUTE,key,"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.accept(a,new Filters(null,null,"","SYNTHETIC_PREPARED_BYTES"))),Job.class);}
    static Claim claim(Duration lease){var j=accept(UUID.randomUUID().toString());return exports.claim(j.id(),"prepared-test",lease).orElseThrow();}
    static Claim claim(){return claim(Duration.ofSeconds(30));}
    static AssetExportPreparedFile file(Work work){return AssetExportPreparedFile.create(work.claim().command(),"a".repeat(64),1,work.databaseNow(),new byte[]{1,2,3,4});}
    static long audits()throws Exception{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_audit")){r.next();return r.getLong(1);}}
    static Claim altered(Claim c,String worker,int fence,Instant until,Command command,boolean reconcile){return new Claim(c.jobId(),worker,fence,c.version(),until,command,reconcile);}
    @Test void workReadChecksCurrentLeaseAndReturnsNoFileBeforePreparation()throws Exception{var c=claim();long audit=audits();var work=exports.loadWork(c);assertNull(work.prepared());assertEquals(c,work.claim());assertTrue(work.databaseNow().isBefore(c.leaseUntil()));assertEquals(audit,audits());}
    @Test void exactBytesAndDescriptorCommitWithOneAuditAndNewLogicalVersion()throws Exception{var c=claim();var f=file(exports.loadWork(c));long audit=audits();var saved=exports.prepare(c,f);assertEquals(c.version()+1,saved.claim().version());assertTrue(f.sameContent(saved.prepared()));assertEquals(audit+1,audits());assertEquals(State.RUNNING,exports.get(access(),c.jobId()).state());assertFalse(saved.prepared().published());}
    @Test void ambiguousPreparationResponseRecoversExactRetainedBytesWithoutAnotherWrite()throws Exception{var c=claim();var f=file(exports.loadWork(c));var first=exports.prepare(c,f);long audit=audits();var second=exports.prepare(c,f);assertEquals(first.claim(),second.claim());assertTrue(first.prepared().sameContent(second.prepared()));assertEquals(audit,audits());}
    @Test void changedContentOrDescriptorCannotRewritePreparedFile()throws Exception{var c=claim();var f=file(exports.loadWork(c));exports.prepare(c,f);long audit=audits();for(var changed:List.of(AssetExportPreparedFile.create(c.command(),"a".repeat(64),1,f.encoding().generatedAt(),new byte[]{9}),AssetExportPreparedFile.create(c.command(),"b".repeat(64),1,f.encoding().generatedAt(),f.bytes()),AssetExportPreparedFile.create(c.command(),"a".repeat(64),2,f.encoding().generatedAt(),f.bytes()))){assertEquals(409,assertThrows(DomainException.class,()->exports.prepare(c,changed)).status);}assertTrue(f.sameContent(exports.loadWork(c).prepared()));assertEquals(audit,audits());}
    @Test void wrongWorkerFenceAndExtendedLeaseCannotReadOrWritePreparedBytes(){var c=claim();var f=file(exports.loadWork(c));exports.prepare(c,f);for(var wrong:List.of(altered(c,"another",c.fencingToken(),c.leaseUntil(),c.command(),false),altered(c,c.worker(),c.fencingToken()+1,c.leaseUntil(),c.command(),false),altered(c,c.worker(),c.fencingToken(),c.leaseUntil().plusSeconds(1),c.command(),false))){assertEquals(409,assertThrows(DomainException.class,()->exports.loadWork(wrong)).status);assertEquals(409,assertThrows(DomainException.class,()->exports.prepare(wrong,f)).status);}}
    @Test void foreignTenantOrCreatorCannotReadRawFileEvenWithAnotherJobId(){var c=claim();var f=file(exports.loadWork(c));exports.prepare(c,f);var a=c.command().acceptedAccess();for(var foreign:List.of(new AssetExportJobState.Access(UUID.randomUUID(),a.actorId(),a.permissionVersion(),a.role(),true),new AssetExportJobState.Access(a.tenantId(),UUID.randomUUID(),a.permissionVersion(),a.role(),true))){var cmd=new Command(foreign,c.command().filters());var wrong=altered(c,c.worker(),c.fencingToken(),c.leaseUntil(),cmd,false);assertEquals(404,assertThrows(DomainException.class,()->exports.loadWork(wrong)).status);var wrongFile=AssetExportPreparedFile.create(cmd,"a".repeat(64),1,f.encoding().generatedAt(),f.bytes());assertEquals(404,assertThrows(DomainException.class,()->exports.prepare(wrong,wrongFile)).status);}}
    @Test void expiredClaimCannotRetrieveOrPrepareBytes()throws Exception{var c=claim(Duration.ofMillis(20));try(var x=pool.getConnection();var s=x.createStatement()){s.execute("SELECT pg_sleep(0.06)");}assertEquals(409,assertThrows(DomainException.class,()->exports.loadWork(c)).status);var f=AssetExportPreparedFile.create(c.command(),"a".repeat(64),1,Instant.EPOCH,new byte[]{1});assertEquals(409,assertThrows(DomainException.class,()->exports.prepare(c,f)).status);}
    @Test void newFenceRecoversSameBytesAndCannotClearReconciliationWithStaleFlag()throws Exception{var c=claim(Duration.ofSeconds(10));var f=file(exports.loadWork(c));exports.prepare(c,f);try(var x=pool.getConnection();var s=x.prepareStatement("SELECT pg_sleep(GREATEST(0,EXTRACT(EPOCH FROM (?::timestamptz-clock_timestamp())))+0.05)")){s.setTimestamp(1,Timestamp.from(c.leaseUntil()));s.execute();}var next=exports.claim(c.jobId(),"reconcile-reader",Duration.ofSeconds(30)).orElseThrow();assertEquals(409,assertThrows(DomainException.class,()->exports.loadWork(c)).status);var offered=altered(next,next.worker(),next.fencingToken(),next.leaseUntil(),next.command(),false);var restored=exports.loadWork(offered);assertTrue(restored.claim().storageReconciliationRequired());assertTrue(f.sameContent(restored.prepared()));long audit=audits();var duplicate=exports.prepare(offered,f);assertTrue(duplicate.claim().storageReconciliationRequired());assertEquals(restored.claim().version(),duplicate.claim().version());assertEquals(audit,audits());}
    @Test void mutationOfReturnedArrayCannotChangePersistedBytes(){var c=claim();var f=file(exports.loadWork(c));exports.prepare(c,f);byte[] obtained=exports.loadWork(c).prepared().bytes();obtained[0]=99;assertArrayEquals(new byte[]{1,2,3,4},exports.loadWork(c).prepared().bytes());}
    @Test void anotherCommandOrInvalidGenerationTimeDoesNotWrite()throws Exception{var c=claim();var work=exports.loadWork(c);long audit=audits();var other=new Command(c.command().acceptedAccess(),new Filters(null,null,null,"different"));assertEquals(400,assertThrows(DomainException.class,()->exports.prepare(c,AssetExportPreparedFile.create(other,"a".repeat(64),1,work.databaseNow(),new byte[]{1}))).status);for(Instant time:List.of(Instant.EPOCH,work.databaseNow().plusSeconds(86400)))assertEquals(400,assertThrows(DomainException.class,()->exports.prepare(c,AssetExportPreparedFile.create(c.command(),"a".repeat(64),1,time,new byte[]{1}))).status);assertNull(exports.loadWork(c).prepared());assertEquals(audit,audits());}
    @Test void freshRepositoryRestoresPreparedBytesWhileOriginalReceiptRemainsUnchanged(){String key=UUID.randomUUID().toString();var original=accept(key);var c=exports.claim(original.id(),"original-receipt",Duration.ofSeconds(30)).orElseThrow();var f=file(exports.loadWork(c));exports.prepare(c,f);var fresh=new PostgresAssetExportRepository(pool,new PostgresPlatformRepository(pool,mapper));assertTrue(f.sameContent(fresh.loadWork(c).prepared()));assertEquals(original,accept(key));}
    @Test void auditFailureRollsBackFileDescriptorAndLogicalVersion()throws Exception{var claim=claim();var f=file(exports.loadWork(claim));long audit=audits();javax.sql.DataSource injected=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(proxy,method,args)->{if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("SYNTHETIC_PREPARE_AUDIT_FAILURE","22012");try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});var faulted=new PostgresAssetExportRepository(injected,new PostgresPlatformRepository(injected,mapper));assertEquals(503,assertThrows(DomainException.class,()->faulted.prepare(claim,f)).status);var after=exports.loadWork(claim);assertNull(after.prepared());assertEquals(claim.version(),after.claim().version());assertEquals(audit,audits());}
}
